The most efficient sorting algorithm for this scenario is the QuickSort algorithm, which has an average time complexity of O(n log n) and a worst-case time complexity of O(n^2). Here's a sample implementation of QuickSort in C++:
```
#include <iostream>
#include <vector>
using namespace std;
int partition(vector<int>& arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return i + 1;
}
void quickSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}
int main() {
    vector<int> arr = {5, 2, -1, 0, 10, 8};
    quickSort(arr, 0, arr.size() - 1);
    for (int i = 0; i < arr.size(); i++) {
        cout << arr[i] << " ";
    }
    return 0;
}
```
In this implementation, the partition function selects the last element as the pivot, and then rearranges the elements in the array such that all elements less than or equal to the pivot are on the left side, and all elements greater than the pivot are on the right side. The quickSort function recursively calls partition on the left and right sides of the pivot until the entire array is sorted.

