What is the best way to create a smooth and graceful random walk path within a given area using Go? I want to be able to control the length and direction of the path. Can you provide an example of how to implement this using Go code? 
Here's an example implementation in Go:
```
package main
import (
    "fmt"
    "math/rand"
    "time"
)
type Point struct {
    X, Y float64
}
type Path struct {
    Points []Point
}
func NewPath() *Path {
    return &Path{[]Point{}}
}
func (p *Path) AddPoint(point Point) {
    p.Points = append(p.Points, point)
}
func GenerateRandomWalkPath(areaWidth, areaHeight, pathLength int) *Path {
    path := NewPath()
    rand.Seed(time.Now().UnixNano())
    currentPoint := Point{float64(rand.Intn(areaWidth)), float64(rand.Intn(areaHeight))}
    path.AddPoint(currentPoint)
    for i := 1; i < pathLength; i++ {
        // Generate a random direction vector
        direction := Point{float64(rand.Intn(3))-1.0, float64(rand.Intn(3))-1.0}
        // Scale the direction vector to have a length of 1
        length := 1 / (direction.X*direction.X + direction.Y*direction.Y)
        direction.X *= length
        direction.Y *= length
        // Move the current point in the random direction
        currentPoint.X += direction.X
        currentPoint.Y += direction.Y
        // Make sure the point stays within the area
        if currentPoint.X < 0 {
            currentPoint.X = 0
        }
        if currentPoint.X >= float64(areaWidth) {
            currentPoint.X = float64(areaWidth) - 1
        }
        if currentPoint.Y < 0 {
            currentPoint.Y = 0
        }
        if currentPoint.Y >= float64(areaHeight) {
            currentPoint.Y = float64(areaHeight) - 1
        }
        // Add the new point to the path
        path.AddPoint(currentPoint)
    }
    return path
}
func main() {
