To analyze a website's domain name and determine its country of origin, you can use the `getaddrinfo()` function in C++. Here is an example code snippet:
```
#include <iostream>
#include <netdb.h>
#include <arpa/inet.h>
int main(int argc, char *argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " hostname" << std::endl;
        return 1;
    }
    struct addrinfo hints, *res;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if ((status = getaddrinfo(argv[1], NULL, &hints, &res)) != 0) {
        std::cerr << "getaddrinfo error: " << gai_strerror(status) << std::endl;
        return 2;
    }
    void *addr;
    std::string ipver;
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);
        ipver = "IPv4";
    } else {
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        addr = &(ipv6->sin6_addr);
        ipver = "IPv6";
    }
    inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);
    std::cout << argv[1] << " is located in " << ipver << " address " << ipstr << std::endl;
    freeaddrinfo(res);
    return 0;
}
```
