end
% Evaluate the fitness of each organism
fitness_scores = zeros(population_size, 1);
for i = 1:population_size
    organism = population(i, :);
    trait1_score = trait1_fitness(round(organism(1) * 3 + 1));
    trait2_score = trait2_fitness(round(organism(2) * 3 + 1));
    trait3_score = trait3_fitness(round(organism(3) * 3 + 1));
    fitness_scores(i) = trait1_score * trait2_score * trait3_score;
end
% Calculate the number of offspring for each organism
total_fitness = sum(fitness_scores);
offspring_counts = round((fitness_scores / total_fitness) * population_size);
% Generate the next generation by selecting the highest-scoring organisms
