Here's a sample code that uses the Google Maps Places API and Yelp API to suggest places to visit, restaurants, and accommodations in Paris:
```java
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
public class ParisItineraryGenerator {
    private static final String GOOGLE_MAPS_API_KEY = "YOUR_GOOGLE_MAPS_API_KEY";
    private static final String YELP_API_KEY = "YOUR_YELP_API_KEY";
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the number of days you will be staying in Paris:");
        int numDays = scanner.nextInt();
        scanner.close();
        List<String> attractions = getAttractions();
        List<String> restaurants = getRestaurants();
        List<String> accommodations = getAccommodations();
        System.out.println("Here is a suggested itinerary for " + numDays + " days in Paris:");
        for (int i = 1; i <= numDays; i++) {
            System.out.println("Day " + i + ":");
            System.out.println("Attraction: " + attractions.get(i - 1));
            System.out.println("Restaurant: " + restaurants.get(i - 1));
            System.out.println("Accommodation: " + accommodations.get(i - 1));
            System.out.println();
        }
    }
    private static List<String> getAttractions() {
        List<String> attractions = new ArrayList<>();
        OkHttpClient client = new OkHttpClient();
        for (int i = 0; i < 3; i++) {
            Request request = new Request.Builder()
                    .url("https://maps.googleapis.com/maps/api/place/textsearch/json?query=attractions+in+Paris&key="
                            + GOOGLE_MAPS_API_KEY).build();
            try {
                Response response = client.newCall(request).execute();
                JSONObject jsonObject = new JSONObject(response.body().string());
                JSONArray results = jsonObject.getJSONArray("results");
                String name = results.getJSONObject(i).getString("name");
                attractions.add(name);
            } catch (IOException | JSONException e) {
                e.printStackTrace();
            }
        }
        return attractions;
    }
    private static List<String> getRestaurants() {
        List<String> restaurants = new ArrayList<>();
        OkHttpClient client = new OkHttpClient();
        for (int i = 0; i < 3; i++) {
            Request request = new Request.Builder()
                    .url("https://api.yelp.com/v3/businesses/search?location=Paris&categories=restaurants&sort_by=rating&limit=1&offset="
                            + i)
                    .header("Authorization", "Bearer " + YELP_API_KEY).build();
            try {
                Response response = client.newCall(request).execute();
                JSONObject jsonObject = new JSONObject(response.body().string());
                JSONArray businesses = jsonObject.getJSONArray("businesses");
                String name = businesses.getJSONObject(0).getString("name");
                restaurants.add(name);
            } catch (IOException | JSONException e) {
                e.printStackTrace();
            }
        }
        return restaurants;
    }
    private static List<String> getAccommodations() {
        List<String> accommodations = new ArrayList<>();
        OkHttpClient client = new OkHttpClient();
        for (int i = 0; i < 3; i++) {
            Request request = new Request.Builder()
                    .url("https://api.yelp.com/v3/businesses/search?location=Paris&categories=hotels&sort_by=rating&limit=1&offset="
                            + i)
                    .header("Authorization", "Bearer " + YELP_API_KEY).build();
            try {
                Response response = client.newCall(request).execute();
                JSONObject jsonObject = new JSONObject(response.body().string());
                JSONArray businesses = jsonObject.getJSONArray("businesses");
                String name = businesses.getJSONObject(0).getString("name");
                accommodations.add(name);
            } catch (IOException | JSONException e) {
                e.printStackTrace();
            }
        }
        return accommodations;
    }
}
```
This code uses the `OkHttpClient` library to make HTTP requests to the Google Maps Places API and Yelp API. The `getAttractions()`, `getRestaurants()`, and `getAccommodations()` methods each make three requests to their respective APIs and return a list of suggested places to visit, restaurants, and accommodations.
Once the lists of attractions, restaurants, and accommodations have been generated, the code prints out a suggested itinerary for the specified number of days in Paris. Note that this code only provides suggestions and does not generate a complete itinerary. You may need to modify the code to fit your specific needs.

