// Define a function to preprocess the text
vector<string> preprocess_text(string text) {
    // Convert to lowercase
    transform(text.begin(), text.end(), text.begin(), ::tolower);
    // Remove punctuation
    text.erase(remove_if(text.begin(), text.end(), ::ispunct), text.end());
    // Tokenize text
    vector<string> tokens;
    istringstream iss(text);
    copy(istream_iterator<string>(iss), istream_iterator<string>(), back_inserter(tokens));
    // Remove stop words
    vector<string> stop_words = {"a", "an", "the", "in", "on", "at", "to", "for", "with", "that", "this", "of", "and", "or", "but", "not"};
    tokens.erase(remove_if(tokens.begin(), tokens.end(), [&stop_words](const string& s) {
        return find(stop_words.begin(), stop_words.end(), s) != stop_words.end();
    }), tokens.end());
    return tokens;
}
// Define a function to extract TF-IDF features
vector<vector<double>> extract_tfidf_features(vector<vector<string>> docs) {
    // Convert docs to a bag of words
    unordered_map<string, int> word_counts;
    for (auto& doc : docs) {
        for (auto& word : doc) {
            word_counts[word]++;
        }
    }
    // Compute inverse document frequency
    int num_docs = docs.size();
    unordered_map<string, double> idf;
    for (auto& [word, count] : word_counts) {
        int doc_freq = 0;
        for (auto& doc : docs) {
            if (find(doc.begin(), doc.end(), word) != doc.end()) {
                doc_freq++;
            }
        }
        idf[word] = log((double)num_docs / doc_freq);
    }
    // Compute TF-IDF features
    vector<vector<double>> tfidf_features;
    for (auto& doc : docs) {
        vector<double> tfidf_vec(word_counts.size(), 0.0);
        for (auto& word : doc) {
            int word_index = distance(word_counts.begin(), word_counts.find(word));
            tfidf_vec[word_index] = (double)count(doc.begin(), doc.end(), word) / doc.size() * idf[word];
        }
        tfidf_features.push_back(tfidf_vec);
    }
    return tfidf_features;
}
// Define a function to perform sentiment analysis
vector<double> perform_sentiment_analysis(vector<string> docs) {
    // Load the Python module for sentiment analysis
    py::scoped_interpreter guard{};
    py::module sentiment_module = py::module::import("sentiment_analysis");
    // Call the sentiment analysis function in Python
    py::list sentiment_scores = sentiment_module.attr("perform_sentiment_analysis")(docs);
    // Convert the Python list to a C++ vector
    vector<double> sentiment_vec;
    for (auto& score : sentiment_scores) {
        sentiment_vec.push_back(score.cast<double>());
    }
    return sentiment_vec;
}
